with valid_employees as (select * from employees where salary > 144000 and (upper(full_name) like '%ENR%' or manager_id = 32)), hire_month_summary as (select date_format(hire_date, 'yyyy-MM') as hire_month, max(salary) - min(salary) as salary_range, max(hire_date) as last_hire_date from valid_employees group by date_format(hire_date, 'yyyy-MM')) select hire_month, salary_range, last_hire_date from hire_month_summary order by salary_range desc;
